<style>.drive-native-gallery{min-height:420px}.drive-gallery-status{display:flex;align-items:center;justify-content:center;gap:.65rem;min-height:320px;color:var(--muted);font-weight:800}.drive-gallery-status.is-error{color:#a52d20}.drive-breadcrumb{display:flex;align-items:center;gap:.4rem;margin-bottom:1.2rem;padding:.75rem 1rem;background:#fff8ed;border:1px solid var(--line);border-radius:.8rem}.drive-breadcrumb button{padding:0;color:var(--forge-brown);font-weight:800;background:none;border:0}.drive-breadcrumb i{color:var(--muted);font-size:.72rem}.drive-folder-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:.8rem;margin-bottom:1.2rem}.drive-folder-card{display:flex;align-items:center;gap:.35rem;padding:.35rem;background:linear-gradient(135deg,#fff8e9,#fff);border:1px solid #ead8bc;border-radius:.9rem;transition:transform .2s,box-shadow .2s}.drive-folder-card:hover{transform:translateY(-2px);box-shadow:0 .7rem 1.5rem rgba(57,36,22,.11)}.drive-folder-open{display:flex;align-items:center;gap:.8rem;flex:1;min-width:0;padding:.65rem;text-align:left;background:none;border:0}.drive-folder-open>i{color:#e8a41e;font-size:2rem}.drive-folder-open span{min-width:0}.drive-folder-open strong,.drive-folder-open small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.drive-folder-open small{color:var(--muted)}.drive-image-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:1rem}.drive-image-card{overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:1rem;box-shadow:0 .6rem 1.4rem rgba(57,36,22,.08);transition:transform .2s,box-shadow .2s}.drive-image-card:hover{transform:translateY(-3px);box-shadow:0 1rem 2rem rgba(57,36,22,.14)}.drive-image-button{display:block;width:100%;padding:0;background:#f4efe8;border:0}.drive-image-button img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover}.drive-image-copy{padding:.85rem}.drive-image-copy strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.drive-image-copy small{display:block;margin-top:.25rem;color:var(--muted)}.drive-image-actions{display:grid;grid-template-columns:1fr auto auto;gap:.5rem;margin-top:.75rem}.drive-preview-body{display:grid;place-items:center;min-height:55vh;background:#16120f}.drive-preview-body img{max-width:100%;max-height:72vh;object-fit:contain}@media(max-width:575px){.drive-folder-grid{grid-template-columns:1fr}.drive-image-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:.65rem}.drive-image-copy{padding:.65rem}.drive-image-actions{grid-template-columns:1fr 1fr}.drive-image-actions .btn{font-size:.7rem}.drive-image-actions .btn:first-child{grid-column:1/-1}}</style>
<style>
.drive-native-gallery{position:relative}.drive-native-gallery.is-refreshing:after{content:'Actualizando…';position:sticky;z-index:5;top:1rem;float:right;margin:-.35rem .2rem 0 0;padding:.55rem .85rem .55rem 2.1rem;color:#fff;font-size:.78rem;font-weight:800;background:rgba(45,34,25,.9);border-radius:2rem;box-shadow:0 .45rem 1rem rgba(0,0,0,.16)}.drive-native-gallery.is-refreshing:before{content:'';position:absolute;z-index:6;top:1.12rem;right:6.9rem;width:.8rem;height:.8rem;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;border-radius:50%;animation:drive-spin .7s linear infinite}@keyframes drive-spin{to{transform:rotate(360deg)}}
.drive-drop-overlay{position:absolute;z-index:20;inset:.75rem;display:flex;visibility:hidden;align-items:center;justify-content:center;flex-direction:column;gap:.35rem;color:#fff;background:rgba(31,94,52,.93);border:3px dashed rgba(255,255,255,.75);border-radius:1rem;opacity:0;pointer-events:none;transition:opacity .16s}.drive-drop-overlay i{font-size:3rem}.drive-drop-overlay strong{font-size:1.25rem}.drive-drop-overlay span{opacity:.85}.drive-native-gallery.is-dragging .drive-drop-overlay,.drive-native-gallery.is-uploading .drive-drop-overlay{visibility:visible;opacity:1}.drive-native-gallery.is-uploading .drive-drop-overlay{background:rgba(45,34,25,.94)}
</style>
<script>
document.addEventListener('DOMContentLoaded',()=>{
 const endpoint=@json(route('admin.drive-gallery.files')),uploadEndpoint=@json(route('admin.drive-gallery.upload')),folderEndpoint=@json(route('admin.drive-gallery.folders.store')),trashEndpoint=@json(route('admin.drive-gallery.items.trash','__ITEM__')),canManage=@json(auth()->user()->can('orders.manage') && $driveConnected),rootId=@json(config('services.drive_gallery.folder_id')),csrf=document.querySelector('meta[name="csrf-token"]').content,grid=document.querySelector('[data-gallery-grid]'),folderGrid=document.querySelector('[data-folder-grid]'),breadcrumb=document.querySelector('[data-gallery-breadcrumb]'),status=document.querySelector('[data-gallery-status]'),refresh=document.querySelector('[data-gallery-refresh]');let library={files:[],folders:[]},currentPath='Principal';
 const escape=value=>{const node=document.createElement('div');node.textContent=value??'';return node.innerHTML};
 const size=bytes=>bytes?`${(bytes/1024/1024).toFixed(bytes>1048576?1:2)} MB`:'Tamaño no disponible';
 const render=()=>{const folders=library.folders.filter(folder=>folder.parent===currentPath),files=library.files.filter(file=>file.folder===currentPath);const parts=currentPath.split(' / ');let path='';breadcrumb.classList.remove('d-none');breadcrumb.innerHTML=parts.map((part,index)=>{path=index===0?part:`${path} / ${part}`;return `${index?'<i class="bi bi-chevron-right"></i>':''}<button type="button" data-folder-path="${encodeURIComponent(path)}">${escape(index===0?'Galería':part)}</button>`}).join('');folderGrid.innerHTML=folders.map(folder=>{const total=library.files.filter(file=>file.folder===folder.path||file.folder.startsWith(`${folder.path} / `)).length,remove=canManage?`<button class="btn btn-sm btn-outline-danger" type="button" data-trash-id="${folder.id}" data-trash-name="${encodeURIComponent(folder.name)}" data-trash-kind="carpeta" title="Enviar carpeta a la papelera"><i class="bi bi-trash"></i></button>`:'';return `<article class="drive-folder-card"><button class="drive-folder-open" type="button" data-folder-path="${encodeURIComponent(folder.path)}"><i class="bi bi-folder-fill"></i><span><strong>${escape(folder.name)}</strong><small>${total} imagen${total===1?'':'es'}</small></span></button>${remove}</article>`}).join('');grid.innerHTML=files.map(file=>{const preview=encodeURIComponent(JSON.stringify(file)),remove=canManage?`<button class="btn btn-sm btn-outline-danger" type="button" data-trash-id="${file.id}" data-trash-name="${encodeURIComponent(file.name)}" data-trash-kind="imagen" title="Enviar a la papelera"><i class="bi bi-trash"></i></button>`:'';return `<article class="drive-image-card"><button class="drive-image-button" type="button" data-preview="${preview}" data-bs-toggle="modal" data-bs-target="#driveImageModal"><img src="${file.thumbnail_url}" alt="${escape(file.name)}" loading="lazy"></button><div class="drive-image-copy"><strong>${escape(file.name)}</strong><small>${size(file.size)}</small><div class="drive-image-actions"><button class="btn btn-sm btn-outline-dark" type="button" data-preview="${preview}" data-bs-toggle="modal" data-bs-target="#driveImageModal"><i class="bi bi-eye me-1"></i>Ver</button><a class="btn btn-sm btn-dark" href="${file.download_url}" title="Descargar"><i class="bi bi-download"></i></a>${remove}</div></div></article>`}).join('');status.hidden=folders.length>0||files.length>0;if(!status.hidden){status.className='drive-gallery-status';status.innerHTML='<i class="bi bi-folder2-open fs-2"></i>Esta carpeta está vacía.'}const location=document.querySelector('[data-folder-location]');if(location)location.textContent=`Se creará dentro de: ${currentPath==='Principal'?'Galería principal':currentPath.replace('Principal / ','')}.`};
 const load=async({preserve=false}={})=>{const gallery=document.querySelector('.drive-native-gallery');refresh.disabled=true;if(preserve){gallery.classList.add('is-refreshing')}else{status.className='drive-gallery-status';status.innerHTML='<span class="spinner-border spinner-border-sm"></span>Cargando imágenes y subcarpetas...';status.hidden=false;folderGrid.innerHTML='';grid.innerHTML='';breadcrumb.classList.add('d-none')}try{const response=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'}),payload=await response.json();if(!response.ok)throw new Error(payload.message||'No se pudo cargar la galería.');library=payload;const select=document.querySelector('[data-upload-folder]');if(select)select.innerHTML=`<option value="{{ config('services.drive_gallery.folder_id') }}">Galería principal</option>`+library.folders.map(folder=>`<option value="${folder.id}">${escape(folder.path.replace('Principal / ',''))}</option>`).join('');render()}catch(error){if(preserve){window.Swal.fire({title:'No se pudo actualizar',text:error.message,icon:'error',confirmButtonText:'Entendido'})}else{status.className='drive-gallery-status is-error';status.innerHTML=`<i class="bi bi-exclamation-triangle-fill"></i>${escape(error.message)}`}}finally{refresh.disabled=false;gallery.classList.remove('is-refreshing')}};
 document.addEventListener('click',async event=>{const trash=event.target.closest('[data-trash-id]');if(trash){const name=decodeURIComponent(trash.dataset.trashName),kind=trash.dataset.trashKind,result=await window.Swal.fire({title:`¿Enviar ${kind} a la papelera?`,text:name,icon:'warning',showCancelButton:true,confirmButtonText:'Sí, enviar',cancelButtonText:'Cancelar',confirmButtonColor:'#b42318'});if(!result.isConfirmed)return;trash.disabled=true;try{const response=await fetch(trashEndpoint.replace('__ITEM__',encodeURIComponent(trash.dataset.trashId)),{method:'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf}}),payload=await response.json();if(!response.ok)throw new Error(payload.message||'No se pudo eliminar el elemento.');await window.Swal.fire({title:'Enviado a la papelera',text:payload.message,icon:'success',confirmButtonText:'Listo'});if(kind==='carpeta'&&currentPath.includes(` / ${name}`))currentPath='Principal';await load({preserve:true})}catch(error){trash.disabled=false;window.Swal.fire({title:'No se pudo eliminar',text:error.message,icon:'error',confirmButtonText:'Entendido'})}return}const folder=event.target.closest('[data-folder-path]');if(folder){currentPath=decodeURIComponent(folder.dataset.folderPath);render();return}const trigger=event.target.closest('[data-preview]');if(!trigger)return;const file=JSON.parse(decodeURIComponent(trigger.dataset.preview));document.querySelector('[data-preview-name]').textContent=file.name;const image=document.querySelector('[data-preview-image]');image.src=file.thumbnail_url;image.alt=file.name;document.querySelector('[data-preview-drive]').href=file.view_url;document.querySelector('[data-preview-download]').href=file.download_url});
 refresh.addEventListener('click',()=>load({preserve:true}));load();
 const folderForm=document.querySelector('[data-folder-form]');folderForm?.addEventListener('submit',async event=>{event.preventDefault();const submit=folderForm.querySelector('[data-folder-submit]'),message=folderForm.querySelector('[data-folder-message]'),currentFolder=library.folders.find(folder=>folder.path===currentPath),parentId=currentPath==='Principal'?rootId:currentFolder?.id;submit.disabled=true;message.classList.add('d-none');try{const response=await fetch(folderEndpoint,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({name:folderForm.elements.name.value,parent_id:parentId})}),payload=await response.json();if(!response.ok)throw new Error(Object.values(payload.errors||{}).flat()[0]||payload.message||'No se pudo crear la carpeta.');document.querySelector('#driveFolderModal [data-bs-dismiss="modal"]')?.click();folderForm.reset();await window.Swal.fire({title:'Carpeta creada',text:payload.message,icon:'success',confirmButtonText:'Listo'});await load({preserve:true})}catch(error){message.textContent=error.message;message.classList.remove('d-none')}finally{submit.disabled=false}});
 const uploadForm=document.querySelector('[data-upload-form]');uploadForm?.addEventListener('submit',event=>{event.preventDefault();const submit=uploadForm.querySelector('[data-upload-submit]'),wrap=uploadForm.querySelector('[data-upload-progress-wrap]'),bar=uploadForm.querySelector('[data-upload-progress]'),percent=uploadForm.querySelector('[data-upload-percent]'),message=uploadForm.querySelector('[data-upload-message]'),xhr=new XMLHttpRequest();submit.disabled=true;wrap.classList.remove('d-none');message.className='alert d-none';xhr.open('POST',uploadEndpoint);xhr.setRequestHeader('Accept','application/json');xhr.setRequestHeader('X-CSRF-TOKEN',document.querySelector('meta[name="csrf-token"]').content);xhr.upload.addEventListener('progress',progress=>{if(!progress.lengthComputable)return;const value=Math.round(progress.loaded/progress.total*100);bar.style.width=`${value}%`;percent.textContent=`${value}%`});xhr.addEventListener('load',async()=>{let payload={};try{payload=JSON.parse(xhr.responseText)}catch{}submit.disabled=false;if(xhr.status<200||xhr.status>=300){message.className='alert alert-danger';message.textContent=Object.values(payload.errors||{}).flat()[0]||payload.message||'No se pudo completar la carga.';return}document.querySelector('#driveUploadModal [data-bs-dismiss="modal"]')?.click();uploadForm.reset();bar.style.width='0';percent.textContent='0%';wrap.classList.add('d-none');await window.Swal.fire({title:'Carga completada',text:payload.message,icon:'success',confirmButtonText:'Listo'});load({preserve:true})});xhr.addEventListener('error',()=>{submit.disabled=false;message.className='alert alert-danger';message.textContent='Se perdió la conexión durante la carga.'});xhr.send(new FormData(uploadForm))});
 const dropZone=document.querySelector('[data-drive-drop-zone]'),dropOverlay=document.querySelector('[data-drive-drop-overlay]');let dragDepth=0;
 if(canManage&&dropZone){document.addEventListener('dragover',event=>event.preventDefault());document.addEventListener('drop',event=>{if(!event.target.closest('[data-drive-drop-zone]'))event.preventDefault()});dropZone.addEventListener('dragenter',event=>{event.preventDefault();dragDepth++;dropZone.classList.add('is-dragging')});dropZone.addEventListener('dragover',event=>{event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect='copy'});dropZone.addEventListener('dragleave',event=>{event.preventDefault();dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)dropZone.classList.remove('is-dragging')});dropZone.addEventListener('drop',event=>{event.preventDefault();dragDepth=0;dropZone.classList.remove('is-dragging');const files=[...(event.dataTransfer?.files||[])];if(!files.length)return;if(files.length>20){window.Swal.fire({title:'Demasiados archivos',text:'Puedes cargar hasta 20 imágenes por operación.',icon:'warning',confirmButtonText:'Entendido'});return}const invalid=files.find(file=>!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>20*1024*1024);if(invalid){window.Swal.fire({title:'Archivo no permitido',text:`${invalid.name} no es una imagen compatible o supera 20 MB.`,icon:'warning',confirmButtonText:'Entendido'});return}const currentFolder=library.folders.find(folder=>folder.path===currentPath),folderId=currentPath==='Principal'?rootId:currentFolder?.id;if(!folderId)return;const data=new FormData();data.append('folder_id',folderId);files.forEach(file=>data.append('images[]',file));const xhr=new XMLHttpRequest();dropZone.classList.add('is-uploading');dropOverlay.querySelector('strong').textContent=`Subiendo ${files.length} imagen${files.length===1?'':'es'}…`;dropOverlay.querySelector('span').textContent='0% completado';xhr.open('POST',uploadEndpoint);xhr.setRequestHeader('Accept','application/json');xhr.setRequestHeader('X-CSRF-TOKEN',csrf);xhr.upload.addEventListener('progress',progress=>{if(progress.lengthComputable)dropOverlay.querySelector('span').textContent=`${Math.round(progress.loaded/progress.total*100)}% completado`});xhr.addEventListener('load',async()=>{let payload={};try{payload=JSON.parse(xhr.responseText)}catch{}dropZone.classList.remove('is-uploading');dropOverlay.querySelector('strong').textContent='Suelta las imágenes aquí';dropOverlay.querySelector('span').textContent='Se cargarán en la carpeta actual';if(xhr.status<200||xhr.status>=300){window.Swal.fire({title:'No se pudo cargar',text:Object.values(payload.errors||{}).flat()[0]||payload.message||'Google Drive rechazó la carga.',icon:'error',confirmButtonText:'Entendido'});return}await window.Swal.fire({title:'Carga completada',text:payload.message,icon:'success',confirmButtonText:'Listo'});load({preserve:true})});xhr.addEventListener('error',()=>{dropZone.classList.remove('is-uploading');dropOverlay.querySelector('strong').textContent='Suelta las imágenes aquí';dropOverlay.querySelector('span').textContent='Se cargarán en la carpeta actual';window.Swal.fire({title:'Se perdió la conexión',text:'No se pudo completar la carga.',icon:'error',confirmButtonText:'Entendido'})});xhr.send(data)})}
});
